/**
 * 구매 금액의 1%를 구매자에게 포인트로 적립하고 혜택 알림을 보냅니다.
 * 1포인트 미만은 버리며, 적립액이 0이면 아무것도 하지 않습니다.
 * 호출 측은 주문을 COMPLETED로 전이한 직후에만 호출해야 주문당 한 번만 적립됩니다.
 *
 * @param order 배송 완료된 주문
 */
private void grantPurchaseReward(Order order) {
    int reward = order.getTotalAmount() / 100;
    if (reward <= 0) {
        log.debug("적립 포인트 없음: orderId={}, totalAmount={}", order.getId(), order.getTotalAmount());
        return;
    }

    User buyer = order.getUser();
    pointRepository.save(new Point(buyer, reward, "구매 적립 (주문 ID: " + order.getId() + ")"));
    log.info("구매 적립 포인트 지급: userId={}, orderId={}, point={}", buyer.getId(), order.getId(), reward);

    notificationCommandService.createNotification(
            buyer.getId(),
            NotificationCategory.SHOPPING,
            NotificationType.BENEFIT,
            String.format("구매 적립 %,dP가 지급되었습니다. 주문 ID: %d", reward, order.getId())
    );
}

